<template><view class="page"><view class="row tabs"><button :class="scope==='joined'?'active':''" @click="change('joined')">我参与的</button><button :class="scope==='created'?'active':''" @click="change('created')">我负责的</button></view><ActivityCard v-for="item in list" :key="item.id" :activity="item" @open="open" /><view v-if="!list.length" class="empty">这里还没有活动</view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import ActivityCard from'@/components/ActivityCard.vue';import{api}from'@/services/api';import{requireSession}from'@/services/session';import type{Activity,PageData}from'@/services/types';const scope=ref('joined'),list=ref<Activity[]>([]);async function load(){if(!requireSession())return;list.value=(await api<PageData<Activity>>(`/activities?scope=${scope.value}&size=50`)).items}onShow(load);async function change(v:string){scope.value=v;await load()}const open=(id:number)=>uni.navigateTo({url:`/pages/activityDetail/activityDetail?id=${id}`})</script>
<style scoped lang="scss">.tabs{margin-bottom:24rpx}button{flex:1;background:#fff}.active{color:$primary;background:$primary-soft}</style>
